arguments.command:
python3 - <<'EOF'
import json, glob

total = 0
count = 0
for f in sorted(glob.glob('data/*.jsonl')):
    for line in open(f):
        line = line.strip()
        if not line:
            continue
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        count += 1
        elapsed = rec.get('body', {}).get('span', {}).get('elapsed')
        if elapsed is None:
            continue
        value = elapsed['value']
        unit = elapsed['unit']
        if unit == 'ms':
            total += value
        elif unit == 'us':
            total += value // 1000
        elif unit == 's':
            total += value * 1000
        else:
            raise ValueError(unit)
print("spans:", count)
print("total:", total)
EOF

